            fill="none"
            stroke={i % 2 ? "#b6c7ad" : "#688d73"}
            strokeWidth={0.7}
            opacity={0.12 + i * 0.04}
          />
        ))}
      </svg>
      <Center
        style={{
          transform: `perspective(700px) rotateY(${tween(t, start, start + 0.5, -8, 0)}deg) rotateZ(${tween(t, start, start + 0.55, 4, 0)}deg)`,
        }}
      >
        <RevealCopy
          text={second ? scene.content.promise : scene.content.industry}
          t={t}
          start={start}
          size={43}
        />
      </Center>
    </div>
  );
}

