  const first = t < 20.62;
  const inset = !first && t < 21.02;
  const age = t - (first ? 20.22 : inset ? 20.62 : 21.02);
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        background: "#eee8d9",
      }}
